test("IContent deserialization fail", () => {
  const jsonable = "This is not a IContent.";

  const instanceOrError = OurJsonization.contentFromJsonable(
    jsonable
  );
  expect(instanceOrError.error.message).toStrictEqual(
    "Expected a JSON object, but got: string"
  );
});

